\section{Introduction}

\subsection{The question}
Rainbow Ramsey theory (anti-Ramsey theory) studies conditions forcing a colouring to contain a
totally multicoloured, or \emph{rainbow}, copy of a prescribed structure. For arithmetic
progressions the paradigm question is: given $k$ colours, how long must an interval of integers
be before a typical, or every, $k$-colouring contains a rainbow $l$-term arithmetic progression?

We study a quantitatively sharper variant. Instead of asking for one rainbow progression, we ask
for the \emph{full spectrum}: every possible colour pattern on a progression must appear. Fix
$l = 2$, decompose an interval into $m$ consecutive blocks $\{2t, 2t+1\}$, and observe the
ordered colour pair on each block. There are $N = k^2$ possible pairs. Define
\[
T_k = \min\bigl\{ m : \text{strictly more than half of all $k$-colourings realise all $k^2$
pairs on } [0,2m) \bigr\}.
\]
The conjecture motivating this work asserted $T_k = \Theta(k^2\log k)$ with computable constants
$c_1, c_2$ satisfying $0.1 \le c_1 \le c_2 \le 10$ and
$\liminf T_k/(k^2\log k) \ge c_1$, $\limsup T_k/(k^2\log k) \le c_2$.
We prove considerably more: the limit exists and equals $2$; the optimal constants coincide,
$c_1 = c_2 = 2$; and admissible explicit constants are $c_1 = 1$, $c_2 = 4$, valid for all
$k \ge 2$.

\subsection{The reduction}
Everything rests on a single reframing. A $k$-colouring of $[0, lm)$, read as $m$ consecutive
$l$-term progressions of common difference $1$, is precisely a word of length $m$ over the
alphabet of $l$-patterns, of which there are $N = k^l$. ``Every pattern appears'' is exactly
``the word is surjective''. Thus the rainbow-AP spectrum question \emph{is} the coupon
collector's problem, with the stopping rule ``probability of completion exceeds $1/2$'' rather
than the more familiar expectation. The classical heuristic gives completion time $N\log N$;
with $N = k^2$ this is $k^2\log(k^2) = 2k^2\log k$, and the constant $2$ is the exponent $l = 2$
escaping from inside a logarithm. Our task is to make this rigorous with a two-sided bound whose
error term is $O(N)$, a factor $\log N$ below the main term.

\section{The full-spectrum framework}

Throughout, $\alpha$ is a finite set (the \emph{alphabet}) with $N = |\alpha| \ge 1$ letters, and
$m \ge 0$ is an integer. A \emph{word of length $m$} is a function
$f : \{0,\dots,m-1\} \to \alpha$; there are $N^m$ of them.

\begin{definition}[Missed letters]
For a word $f$ of length $m$, set
$\Miss(f) = \{ a \in \alpha : f(x) \ne a \text{ for all } x \}$ and
$\miss(f) = |\Miss(f)|$.
\end{definition}

\begin{lemma}[Full spectrum equals surjectivity]\label{lem:surj}
$\miss(f) = 0$ if and only if $f$ is surjective.
\end{lemma}

\begin{proof}
If $f$ omits $a$ then $a \in \Miss(f)$, so $\miss(f) > 0$; conversely any element of $\Miss(f)$
is omitted.
\end{proof}

\begin{definition}[Deficient and full-spectrum words]
Let $\mathcal D_m = \{ f : \miss(f) > 0\}$, $D_m = |\mathcal D_m|$, and
$\mathcal S_m = \{f : \miss(f) = 0\}$, $S_m = |\mathcal S_m|$. Then $S_m + D_m = N^m$.
\end{definition}

\begin{definition}[Full-spectrum threshold]\label{def:thr}
$T(\alpha) = \min\{ m \ge 0 : 2D_m < N^m \}$, the least word length at which a strict majority
of words is surjective.
\end{definition}

\begin{lemma}[Avoiding a set]\label{lem:avoid}
For $S \subseteq \alpha$ with $|S| = r$, the number of words of length $m$ avoiding every letter
of $S$ is $(N-r)^m$.
\end{lemma}

\begin{proof}
Such words are exactly the words over the $(N-r)$-letter alphabet $\alpha \setminus S$.
\end{proof}

\begin{lemma}[Subset criterion]\label{lem:subset}
For a word $f$ and $S \subseteq \alpha$: $S \subseteq \Miss(f)$ if and only if $f(x) \notin S$
for every position $x$.
\end{lemma}

\begin{proof}
Both sides say that no position of $f$ carries a letter of $S$.
\end{proof}

\section{Exact moments of all orders}

\begin{theorem}[Binomial Moment Identity]\label{thm:moments}
For every $r \ge 0$ and every $m \ge 0$,
\[
\sum_{f : \{0,\dots,m-1\} \to \alpha} \binom{\miss(f)}{r}
= \binom{N}{r}\,(N-r)^m .
\]
\end{theorem}

\begin{proof}
Both sides count
$\mathcal P = \{(f,S) : |S| = r,\ S \subseteq \Miss(f)\}$.
Fixing $f$ and counting admissible $S$ gives $\binom{\miss(f)}{r}$; summing over $f$ gives the
left side. Fixing $S$ first there are $\binom{N}{r}$ choices, and by
Lemmas~\ref{lem:avoid} and~\ref{lem:subset} the words $f$ with $S \subseteq \Miss(f)$ are exactly
the words avoiding $S$, of which there are $(N-r)^m$.
\end{proof}

\begin{corollary}[First moment]\label{cor:m1}
$\sum_f \miss(f) = N(N-1)^m$.
\end{corollary}

\begin{corollary}[Second moment]\label{cor:m2}
$\sum_f \miss(f)^2 = N(N-1)^m + N(N-1)(N-2)^m$.
\end{corollary}

\begin{proof}
Combine the cases $r = 1, 2$ of Theorem~\ref{thm:moments} with the pointwise identity
$n^2 = 2\binom{n}{2} + n$ (induction on $n$, using $\binom{n+1}{2} = \binom n2 + n$):
$\sum_f \miss(f)^2 = 2\binom N2 (N-2)^m + N(N-1)^m$.
\end{proof}

An independent proof of Corollary~\ref{cor:m2} expands
$\miss(f)^2 = \sum_{a}\sum_b \mathbf 1[f \text{ avoids } a \text{ and } b]$, exchanges the order
of summation, and splits into the diagonal terms $b = a$ (contributing $(N-1)^m$ each) and the
$N-1$ off-diagonal terms (contributing $(N-2)^m$ each).

\subsection{Probabilistic reading}
Dividing Theorem~\ref{thm:moments} by $N^m$, for a uniformly random word,
\[
\EE\binom{\miss}{r} = \binom Nr\Bigl(1 - \frac rN\Bigr)^m
\sim \frac{1}{r!}\bigl(Ne^{-m/N}\bigr)^r ,
\]
which is the binomial-moment sequence of a Poisson variable of mean $\lambda = Ne^{-m/N}$. Thus
$\miss$ is asymptotically $\mathrm{Poisson}(Ne^{-m/N})$ and the probability of full spectrum is
asymptotically $\exp(-Ne^{-m/N})$.

\section{Two majority criteria}

\begin{lemma}[Union bound]\label{lem:union}
$D_m \le N(N-1)^m$.
\end{lemma}

\begin{proof}
Every deficient word has $\miss(f) \ge 1$, and words outside $\mathcal D_m$ contribute nothing,
so $D_m \le \sum_{f \in \mathcal D_m}\miss(f) = \sum_f \miss(f) = N(N-1)^m$ by
Corollary~\ref{cor:m1}.
\end{proof}

\begin{theorem}[Union-bound criterion]\label{thm:ub}
If $2N(N-1)^m < N^m$, then $2D_m < N^m$: a strict majority of words of length $m$ has full
spectrum.
\end{theorem}

\begin{proof}
$2D_m \le 2N(N-1)^m < N^m$ by Lemma~\ref{lem:union}.
\end{proof}

\begin{lemma}[Cauchy--Schwarz]\label{lem:cs}
$\bigl(\sum_f \miss(f)\bigr)^2 \le D_m \sum_f \miss(f)^2$.
\end{lemma}

\begin{proof}
$\miss$ vanishes off $\mathcal D_m$, so the left side is
$\bigl(\sum_{f \in \mathcal D_m}\miss(f)\bigr)^2 \le
|\mathcal D_m|\sum_{f\in\mathcal D_m}\miss(f)^2 \le D_m\sum_f \miss(f)^2$.
\end{proof}

\begin{theorem}[Second-moment criterion]\label{thm:sm}
Let $N \ge 2$. If $N^m < (N+1)(N-1)^m$, then $N^m < 2D_m$: a strict majority of words of length
$m$ is deficient.
\end{theorem}

\begin{proof}
Write $A = (N-1)^m$ and $B = (N-2)^m$. Corollaries~\ref{cor:m1}--\ref{cor:m2} and
Lemma~\ref{lem:cs} give
\begin{equation}\label{eq:cs}
(NA)^2 \le D_m\bigl(NA + N(N-1)B\bigr).
\end{equation}
Two elementary estimates. First, $N^m B = (N(N-2))^m \le ((N-1)^2)^m = A^2$, since
$N(N-2) = (N-1)^2 - 1$. Second, multiplying the hypothesis $N^m < (N+1)A$ by $A > 0$ gives
$N^m A < (N+1)A^2$. Hence
\[
N^m\bigl(NA + N(N-1)B\bigr) = N\,N^mA + N(N-1)N^mB
< N(N+1)A^2 + N(N-1)A^2 = 2(NA)^2 .
\]
Multiplying \eqref{eq:cs} by $N^m$ and comparing yields
$N^m(NA)^2 < 2 D_m (NA)^2$, and dividing by $(NA)^2 > 0$ gives $N^m < 2D_m$.
\end{proof}

\section{The transition is genuine}

\begin{lemma}[Extension injection]\label{lem:ext}
$N\,S_m \le S_{m+1}$.
\end{lemma}

\begin{proof}
The map $(a,f) \mapsto f{\cdot}a$ appending the letter $a$ sends $\alpha \times \mathcal S_m$
into $\mathcal S_{m+1}$ (appending cannot destroy surjectivity) and is injective (the last letter
recovers $a$, restriction recovers $f$).
\end{proof}

\begin{lemma}[One-step propagation]\label{lem:step}
Let $N \ge 1$. If $2D_m < N^m$ then $2D_{m+1} < N^{m+1}$.
\end{lemma}

\begin{proof}
From $S_m + D_m = N^m$ we get $N^m < 2S_m$. Multiplying by $N$ and using Lemma~\ref{lem:ext},
$N^{m+1} < 2NS_m \le 2S_{m+1}$, which rearranges to $2D_{m+1} < N^{m+1}$.
\end{proof}

\begin{theorem}[Monotonicity]\label{thm:mono}
Let $N \ge 1$ and $m \le m'$. If $2D_m < N^m$ then $2D_{m'} < N^{m'}$.
\end{theorem}

\begin{proof}
Induction on $m'$ using Lemma~\ref{lem:step}.
\end{proof}

\begin{theorem}[Genuine phase transition]\label{thm:iff}
Let $N \ge 2$ and suppose the defining set of Definition~\ref{def:thr} is nonempty
(Corollary~\ref{cor:nonempty}). Then for every $m$,
\[
2D_m < N^m \iff m \ge T(\alpha).
\]
\end{theorem}

\begin{proof}
$(\Rightarrow)$ is minimality. $(\Leftarrow)$: $T(\alpha)$ belongs to the set, and
Theorem~\ref{thm:mono} propagates the property upward.
\end{proof}

\section{Analytic bounds: the sharp window}

\begin{lemma}\label{lem:low}
Let $N \ge 2$ and let $m$ be an integer with $m < (N-1)\log(N+1)$. Then
$N^m < (N+1)(N-1)^m$.
\end{lemma}

\begin{proof}
Let $x = N/(N-1)$. Since $\log t \le t-1$, $\log x \le 1/(N-1)$, so
$m\log x \le m/(N-1) < \log(N+1)$; exponentiating gives $x^m < N+1$.
\end{proof}

\begin{lemma}\label{lem:high}
Let $N \ge 2$ and let $m$ be an integer with $m > N\log(2N)$. Then $2N(N-1)^m < N^m$.
\end{lemma}

\begin{proof}
From $1 + t \le e^t$ with $t = -1/N$ we get $(N-1)/N \le e^{-1/N}$, so
$((N-1)/N)^m \le e^{-m/N} < e^{-\log(2N)} = 1/(2N)$, using $m/N > \log(2N)$.
\end{proof}

\begin{corollary}[Nonemptiness]\label{cor:nonempty}
For $N \ge 2$ the set $\{m : 2D_m < N^m\}$ contains $\lfloor N\log(2N)\rfloor + 1$.
\end{corollary}

\begin{theorem}[Two-sided bound]\label{thm:twosided}
For every finite alphabet with $N \ge 2$ letters,
\[
(N-1)\log(N+1) \;\le\; T(\alpha) \;\le\; N\log(2N) + 1 .
\]
\end{theorem}

\begin{proof}
The upper bound is Corollary~\ref{cor:nonempty}. For the lower bound, if
$T := T(\alpha) < (N-1)\log(N+1)$ then Lemma~\ref{lem:low} and Theorem~\ref{thm:sm} give
$N^{T} < 2D_{T}$, contradicting $2D_T < N^T$, which holds by minimality.
\end{proof}

\begin{lemma}\label{lem:logsucc}
For $N \ge 2$, $\log(N+1) \le \log N + 1$.
\end{lemma}

\begin{theorem}[Sharp window]\label{thm:window}
For every finite alphabet with $N \ge 2$ letters,
\[
\bigl|T(\alpha) - N\log N\bigr| \;\le\; N\log 2 + \log N + 1 .
\]
\end{theorem}

\begin{proof}
Theorem~\ref{thm:twosided} and $\log(2N) = \log 2 + \log N$ give
$T(\alpha) \le N\log N + N\log 2 + 1$. Conversely
$(N-1)\log(N+1) \ge (N-1)\log N \ge N\log N - \log N$, so
$T(\alpha) \ge N\log N - \log N$.
\end{proof}

\section{The rainbow pair-spectrum threshold}

\begin{definition}
For $k \ge 2$, let $T_k = T(\alpha)$ for the alphabet of ordered colour pairs, so $N = k^2$.
\end{definition}

\begin{theorem}[Lower bound]\label{thm:Tlow}
For all $k \ge 2$, $\;2k^2\log k - 2\log k \le T_k$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:twosided} with $N = k^2$ gives $T_k \ge (k^2-1)\log(k^2+1) \ge
(k^2-1)\cdot 2\log k = 2k^2\log k - 2\log k$.
\end{proof}

\begin{theorem}[Upper bound]\label{thm:Tup}
For all $k \ge 2$, $\;T_k \le 2k^2\log k + k^2\log 2 + 1$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:twosided} with $N = k^2$: $T_k \le k^2\log(2k^2)+1 = k^2(\log 2 + 2\log k)+1$.
\end{proof}

\begin{theorem}[Sharp window for $T_k$]
For all $k \ge 2$, $\;\bigl|T_k - 2k^2\log k\bigr| \le k^2\log 2 + 2\log k + 1$.
\end{theorem}

\begin{theorem}[$\Theta(k^2\log k)$ with explicit constants]\label{thm:theta}
With $c_1 = 1$ and $c_2 = 4$, which satisfy $0.1 \le c_1 \le c_2 \le 10$, we have for all
$k \ge 2$
\[
c_1 k^2\log k \;\le\; T_k \;\le\; c_2 k^2\log k .
\]
\end{theorem}

\begin{proof}
Lower: by Theorem~\ref{thm:Tlow},
$T_k \ge k^2\log k + (k^2-2)\log k \ge k^2\log k$ since $k^2 \ge 4$.
Upper: by Theorem~\ref{thm:Tup}, $\log 2 \le \log k$ and $1 \le k^2\log k$, so
$T_k \le 2k^2\log k + k^2\log k + k^2\log k = 4k^2\log k$.
\end{proof}

\begin{theorem}[Exact asymptotic constant]\label{thm:limit}
$\displaystyle \lim_{k\to\infty}\frac{T_k}{k^2\log k} = 2$.
\end{theorem}

\begin{proof}
Dividing Theorems~\ref{thm:Tlow} and~\ref{thm:Tup} by $k^2\log k > 0$,
\[
2 - \frac{2}{k^2} \;\le\; \frac{T_k}{k^2\log k} \;\le\;
2 + \frac{\log 2}{\log k} + \frac{1}{k^2\log k},
\]
and both bounds tend to $2$.
\end{proof}

\begin{corollary}
$\liminf_{k\to\infty} T_k/(k^2\log k) = \limsup_{k\to\infty} T_k/(k^2\log k) = 2$; in
particular the optimal constants coincide, $c_1 = c_2 = 2$.
\end{corollary}

\begin{theorem}[Sharpened constants]
For all $k \ge 100$, $\;1.9\,k^2\log k \le T_k \le 2.2\,k^2\log k$.
\end{theorem}

\begin{proof}
For $k \ge 100$ one has $k^2 \ge 10^4$ and $\log k \ge 6\log 2$. Then $2\log k \le
0.1k^2\log k$, giving the lower bound from Theorem~\ref{thm:Tlow}; and
$k^2\log 2 \le \tfrac16 k^2\log k$ together with $1 \le 0.001 k^2\log k$ gives the upper bound
from Theorem~\ref{thm:Tup}.
\end{proof}

\section{Small cases and numerical evidence}

\begin{proposition}[Numerical criteria]\label{prop:num}
For $k \ge 2$ and $m \ge 0$: if $2k^2(k^2-1)^m < (k^2)^m$ then $T_k \le m$; and if
$(k^2)^m < (k^2+1)(k^2-1)^m$ then $m < T_k$.
\end{proposition}

\begin{proof}
The first is Theorem~\ref{thm:ub} with minimality; the second is Theorem~\ref{thm:sm} together
with Theorem~\ref{thm:iff}.
\end{proof}

\begin{theorem}[Verified windows]
$6 \le T_2 \le 8$, $\;20 \le T_3 \le 25$, $\;44 \le T_4 \le 54$.
\end{theorem}

\begin{proof}
Apply Proposition~\ref{prop:num} at $(k,m) = (2,5),(2,8),(3,19),(3,25),(4,43),(4,54)$; each is a
comparison of explicit integers.
\end{proof}

