INPUT: alphabet size N >= 2
OUTPUT: the exact threshold T(N)

function SURJECTIVE-COUNT(N, m):
    total <- 0
    for j <- 0 to N:
        term <- C(N, j) * (N - j)^m          # exact integers
        total <- total + (-1)^j * term
    return total

function MAJORITY-SURJECTIVE(N, m):
    return 2 * SURJECTIVE-COUNT(N, m) > N^m

function THRESHOLD(N):
    m <- max(0, floor((N - 1) * log(N + 1)) - 1)   # proved lower bound
    while not MAJORITY-SURJECTIVE(N, m):
        m <- m + 1
    return m                                       # monotone, so this is minimal

function PAIR-THRESHOLD(k):
    return THRESHOLD(k * k)                        # rainbow pair spectrum

algorithms.code:
"""Exact computation of the full-spectrum (coupon-collector) threshold T(N).

T(N) is the least word length m at which a strict majority of the N**m words
over an N-letter alphabet is surjective.  The surjective count is given by
inclusion-exclusion over the set of omitted letters,

    S(N, m) = sum_{j=0}^{N} (-1)^j C(N, j) (N - j)**m,

and T(N) is found by scanning m upward from the analytic lower bound
(N-1) log(N+1), which is proved to be a valid starting point.  Monotonicity of
the surjective majority guarantees the first m found is the threshold.
"""

from __future__ import annotations

from math import comb, log
from typing import List


def surjective_count(n_letters: int, length: int) -> int:
    """Number of length-`length` words over `n_letters` letters using all of them."""
    return sum(
        (-1) ** j * comb(n_letters, j) * (n_letters - j) ** length
        for j in range(n_letters + 1)
    )


def majority_surjective(n_letters: int, length: int) -> bool:
    """True iff strictly more than half of all words of this length are surjective."""
    return 2 * surjective_count(n_letters, length) > n_letters**length


def full_spectrum_threshold(n_letters: int) -> int:
    """The exact threshold T(N).

    Starts the scan at the proved lower bound floor((N-1) log(N+1)), which is
    safe because no smaller length can achieve the surjective majority.
    """
    if n_letters <= 1:
        return 0
    start = max(0, int((n_letters - 1) * log(n_letters + 1)) - 1)
    m = start
    while not majority_surjective(n_letters, m):
        m += 1
    return m


def pair_spectrum_threshold(k: int) -> int:
    """The rainbow pair-spectrum threshold T_k = T(k^2)."""
    return full_spectrum_threshold(k * k)


def threshold_table(k_values: List[int]) -> List[tuple]:
    """(k, N, T_k, T_k / (k^2 log k)) for each requested number of colours."""
    rows = []
    for k in k_values:
        t = pair_spectrum_threshold(k)
        rows.append((k, k * k, t, t / (k**2 * log(k))))
    return rows


if __name__ == "__main__":
    for k, n, t, ratio in threshold_table([2, 3, 4, 5, 6, 7, 8, 9, 10]):
        print(f"k={k:>3}  N={n:>4}  T_k={t:>5}  T_k/(k^2 log k)={ratio:.4f}")

