INPUT: alphabet size N >= 2
OUTPUT: integers lo <= T(N) <= hi, certified by the proved criteria

function UNION-BOUND-CRITERION(N, m):      # implies T(N) <= m
    return 2 * N * (N - 1)^m < N^m

function SECOND-MOMENT-CRITERION(N, m):    # implies m < T(N)
    return N^m < (N + 1) * (N - 1)^m

function BINARY-SEARCH-FIRST-TRUE(P, lo, hi):
    while lo < hi:
        mid <- floor((lo + hi) / 2)
        if P(mid) then hi <- mid else lo <- mid + 1
    return lo

function CERTIFIED-BRACKET(N):
    limit <- floor(N * log(2N)) + 3                       # proved upper bound
    hi <- BINARY-SEARCH-FIRST-TRUE(m -> UNION-BOUND-CRITERION(N, m), 0, limit)
    lo <- BINARY-SEARCH-FIRST-TRUE(m -> not SECOND-MOMENT-CRITERION(N, m), 0, hi)
    return (lo, hi)

algorithms.code:
"""Certified bracketing of the full-spectrum threshold by the two moment criteria.

Two purely arithmetic inequalities, both proved, bracket T(N) without ever
enumerating or counting surjections:

    union bound      2 N (N-1)^m < N^m        implies  T(N) <= m
    second moment    N^m < (N+1)(N-1)^m       implies  m < T(N)

Because the surjective-majority property is monotone in m, each criterion is
itself monotone, so the two crossing points can be located by binary search on
m.  Each test is a comparison of two integers of O(m log N) bits, so a single
test costs O(M(m log N)) time with M the integer-multiplication cost; the
binary search performs O(log m) tests.  For N = k^2 the bracket has width
O(N) = O(k^2), i.e. a factor log k below the threshold itself.
"""

from __future__ import annotations

from math import log
from typing import Tuple


def union_bound_criterion(n_letters: int, length: int) -> bool:
    """Proved: if True then the majority of words of this length is surjective."""
    return 2 * n_letters * (n_letters - 1) ** length < n_letters**length


def second_moment_criterion(n_letters: int, length: int) -> bool:
    """Proved: if True then the majority of words of this length is deficient."""
    return n_letters**length < (n_letters + 1) * (n_letters - 1) ** length


def _binary_search_first_true(predicate, lo: int, hi: int) -> int:
    """Least m in [lo, hi] with predicate(m) true, assuming predicate is monotone."""
    while lo < hi:
        mid = (lo + hi) // 2
        if predicate(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo


def certified_bracket(n_letters: int) -> Tuple[int, int]:
    """Return (lo, hi) with lo <= T(N) <= hi, using only the proved criteria."""
    if n_letters < 2:
        return (0, 0)
    # A generous but valid upper search limit: N log(2N) + 2.
    limit = int(n_letters * log(2 * n_letters)) + 3
    hi = _binary_search_first_true(
        lambda m: union_bound_criterion(n_letters, m), 0, limit
    )
    # lo: the least m at which the second-moment obstruction stops firing.
    lo = _binary_search_first_true(
        lambda m: not second_moment_criterion(n_letters, m), 0, hi
    )
    return (lo, hi)


def analytic_bracket(n_letters: int) -> Tuple[float, float]:
    """The closed-form bracket (N-1) log(N+1) <= T(N) <= N log(2N) + 1."""
    n = float(n_letters)
    return ((n - 1.0) * log(n + 1.0), n * log(2.0 * n) + 1.0)


if __name__ == "__main__":
    for n in (4, 9, 16, 25, 36, 49, 64, 100, 400, 2500):
        lo, hi = certified_bracket(n)
        alo, ahi = analytic_bracket(n)
        print(
            f"N={n:>5}  integer bracket [{lo:>6}, {hi:>6}]   "
            f"analytic bracket [{alo:>9.2f}, {ahi:>9.2f}]   width={hi - lo}"
        )

