INPUT: alphabet size N, Bonferroni depth j
OUTPUT: integers lo < hi bracketing the median of the transition

function BINOMIAL-MOMENT(N, m, r):
    return C(N, r) * (1 - r / N)^m         # exact r-th binomial moment

function BONFERRONI-BOUNDS(N, m, j):
    lower <- sum_{r=1}^{2j}   (-1)^(r-1) * BINOMIAL-MOMENT(N, m, r)
    upper <- sum_{r=1}^{2j+1} (-1)^(r-1) * BINOMIAL-MOMENT(N, m, r)
    return (max(0, lower), min(1, upper))   # bounds on P(miss >= 1)

function LOCALISE-MEDIAN(N, j):
    centre <- floor(N * log N + N * log(1 / log 2))   # Poisson prediction
    window <- [centre - max(8, N), centre + max(8, N)]
    lo <- (first m in window with lower bound <= 1/2) - 1
    hi <-  first m in window with upper bound <  1/2
    return (lo, hi)
